type agreementCalloutHeadingLine struct {
	Text      string
	Positions []int
}

type agreementCalloutHeadingModel struct {
	Projected   string
	Positions   []int
	Openers     []graph.Span
	Plain, Page agreementMixedNamespaceReading
	IDs         []string
	Native      agreementNativeHeadingSource
	Valid       bool
}

var agreementCalloutHeadingOpening = regexp.MustCompile(`^\s*>\s*\[!([A-Za-z0-9_-]+)\]([+-]?)\s?(.*)$`)

var agreementCalloutHeadingQuote = regexp.MustCompile(`^\s*>\s?`)

// A callout shell separates its own body from the surrounding paragraph. The
// inserted comments carry no heading words, and every retained byte still names
// its original source position. Code prevents this reading from owning a difference.
func agreementCalloutHeadingRead(body string) agreementCalloutHeadingModel {
	r := agreementCalloutHeadingModel{}
	if !utf8.ValidString(body) || strings.ContainsAny(body, "`~") || strings.Contains(body, "<!--agreement-callout-") {
		return r
	}
	cut := agreementCommentCutP0Reading(body)
	src, positions := cut.Projected, cut.Positions
	if len(cut.Check.Comments) == 0 {
		src = body
		positions = make([]int, len(body))
		for i := range positions {
			positions[i] = i
		}
	} else if !cut.Valid {
		return r
	}
	if len(src) != len(positions) {
		return r
	}
	var neutral strings.Builder
	var kept []int
	for at, c := range src {
		size := utf8.RuneLen(c)
		if strings.ContainsRune(agreementNeutralHeadingRunes, c) {
			continue
		}
		if size < 1 || at+size > len(src) {
			return r
		}
		neutral.WriteString(src[at : at+size])
		kept = append(kept, positions[at:at+size]...)
	}
	src = neutral.String()
	lines := []agreementCalloutHeadingLine{}
	at := 0
	for line := range strings.SplitSeq(src, "\n") {
		lines = append(lines, agreementCalloutHeadingLine{line, slices.Clone(kept[at : at+len(line)])})
		at += len(line) + 1
	}
	var out strings.Builder
	inject := func(s string) {
		out.WriteString(s)
		for range len(s) {
			r.Positions = append(r.Positions, -1)
		}
	}
	writeLine := func(line agreementCalloutHeadingLine) {
		out.WriteString(line.Text)
		r.Positions = append(r.Positions, line.Positions...)
		inject("\n")
	}
	var scan func([]agreementCalloutHeadingLine) bool
	scan = func(input []agreementCalloutHeadingLine) bool {
		for i := 0; i < len(input); {
			line := input[i]
			if !agreementCalloutHeadingOpening.MatchString(line.Text) {
				writeLine(line)
				i++
				continue
			}
			if len(line.Positions) != len(line.Text) || len(line.Positions) == 0 {
				return false
			}
			span := graph.Span{Start: line.Positions[0], Stop: line.Positions[len(line.Positions)-1] + 1}
			if span.Start < 0 || span.Stop > len(body) || !agreementCalloutHeadingOpening.MatchString(body[span.Start:span.Stop]) {
				return false
			}
			r.Openers = append(r.Openers, span)
			i++
			var children []agreementCalloutHeadingLine
			for i < len(input) && strings.HasPrefix(strings.TrimSpace(input[i].Text), ">") {
				if agreementCalloutHeadingOpening.MatchString(input[i].Text) {
					break
				}
				current := input[i]
				prefix := agreementCalloutHeadingQuote.FindString(current.Text)
				if prefix == "" {
					return false
				}
				children = append(children, agreementCalloutHeadingLine{current.Text[len(prefix):], slices.Clone(current.Positions[len(prefix):])})
				i++
			}
			inject("\n<!--agreement-callout-open-->\n\n")
			if !scan(children) {
				return false
			}
			inject("\n<!--agreement-callout-close-->\n\n")
		}
		return true
	}
	if !scan(lines) || len(r.Openers) == 0 {
		return r
	}
	r.Projected = out.String()
	if len(r.Projected) != len(r.Positions) {
		return r
	}
	last := -1
	for i, at := range r.Positions {
		if at < 0 {
			continue
		}
		if at >= len(body) || at <= last || r.Projected[i] != body[at] {
			return r
		}
		last = at
	}
	r.Plain = agreementMixedNamespaceRead(r.Projected, agreementFootnoteGrammar)
	r.Page = agreementMixedNamespaceRead(r.Projected, agreementExclusiveCodeGrammar)
	r.Native = agreementNativeHeadingReading(body)
	if !r.Plain.Eligible || !r.Page.Eligible || !cmp.Equal(r.Plain, r.Page) || !slices.Equal(r.Native.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	if len(r.Native.Native.Code) != 0 || len(r.Native.Check.Code) != 0 {
		return r
	}
	r.IDs = agreementProseNeutralAllocate(r.Page.Bases)
	r.Valid = true
	return r
}

type agreementCalloutHeadingSource struct {
	Original, PrivateReading    agreementCalloutHeadingModel
	Native, PrivateNative       agreementNativeHeadingSource
	IDs, PrivateIDs             []string
	Private                     string
	OriginalSpan, ProjectedSpan graph.Span
	Ordinal                     int
	Valid                       bool
}

// Callout shells separate their body from the surrounding paragraph before
// heading words are read. Bind both whole readings, the complete allocation
// and the original byte before a missing check name can own the difference.
func agreementCalloutHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementCalloutHeadingSource {
	r := agreementCalloutHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Original = agreementCalloutHeadingRead(body)
	a := &r.Original
	if !a.Valid || !slices.Equal(a.IDs, page.Headings) || a.Native.Names[f.Fragment] {
		return r
	}
	r.IDs, r.Native = a.IDs, a.Native
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(a.Page.Headings) {
		return r
	}
	span := a.Page.Headings[r.Ordinal]
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(a.Positions) {
		return r
	}
	found := -1
	for at := span.Start; at < span.Stop; at++ {
		if a.Projected[at] != 'A' {
			continue
		}
		protected := false
		for _, field := range a.Page.Fields {
			if field.Span.Start <= at && at < field.Span.Stop {
				protected = true
			}
		}
		for _, code := range a.Page.Code {
			if code.Start <= at && at < code.Stop {
				protected = true
			}
		}
		if !protected {
			found = at
			break
		}
	}
	if found < 0 {
		return r
	}
	r.ProjectedSpan = graph.Span{Start: found, Stop: found + 1}
	start := a.Positions[found]
	if start < 0 || start >= len(body) || body[start] != 'A' {
		return r
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + 1}
	private := []byte(body)
	private[start] = 'q'
	r.Private = string(private)
	r.PrivateReading = agreementCalloutHeadingRead(r.Private)
	b := &r.PrivateReading
	if !b.Valid || !slices.Equal(a.Positions, b.Positions) || !slices.Equal(a.Native.Check.Targets, b.Native.Check.Targets) {
		return r
	}
	expected := []byte(a.Projected)
	expected[found] = 'q'
	if string(expected) != b.Projected || !cmp.Equal(a.Page.Headings, b.Page.Headings) || !cmp.Equal(a.Page.Code, b.Page.Code) || !cmp.Equal(a.Page.Fields, b.Page.Fields) || len(a.Page.Bases) != len(b.Page.Bases) || len(a.Page.Checks) != len(b.Page.Checks) {
		return r
	}
	for i := range a.Page.Bases {
		if i == r.Ordinal {
			if a.Page.Bases[i] == b.Page.Bases[i] || a.Page.Checks[i] == b.Page.Checks[i] {
				return r
			}
		} else if a.Page.Bases[i] != b.Page.Bases[i] || a.Page.Checks[i] != b.Page.Checks[i] {
			return r
		}
	}
	r.PrivateIDs, r.PrivateNative = b.IDs, b.Native
	r.Valid = true
	return r
}
func agreementCalloutHeadingProjection(source *agreementCalloutHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementSeparateNamespaceHeadingEquation(source.IDs, source.Native.Names, before) || !agreementSeparateNamespaceHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}

