func agreementCalloutHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementCalloutHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementCalloutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementCalloutHeadingSelected(t *testing.T, r *agreementCalloutHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique callout heading declaration")
	}
	return selected
}
func TestAgreementCalloutHeadingOwnedSource(t *testing.T) {
	rows := agreementCalloutHeadingDeclarations()
	if len(rows) != 19 {
		t.Fatal("caught: complete callout heading declaration set")
	}
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			selected := agreementCalloutHeadingSelected(t, r)
			source := agreementCalloutHeadingReading(r.Body, &selected, &r.Page)
			if !source.Valid || !cmp.Equal(source, r.Source) || source.Private != r.Private {
				t.Fatalf("caught: complete callout heading physical source and whole namespace (-want +got):\n%s", cmp.Diff(r.Source, source))
			}
			span := source.OriginalSpan
			private := []byte(r.Body)
			if span.Start < 0 || span.Stop > len(private) || span.Stop <= span.Start {
				t.Fatal("caught: physical callout heading interval")
			}
			copy(private[span.Start:span.Stop], strings.Repeat("q", span.Stop-span.Start))
			if string(private) != r.Private || source.Ordinal < 0 || source.IDs[source.Ordinal] != selected.Fragment || !agreementCalloutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: complete callout heading signed source projection")
			}
		})
	}
}
func TestAgreementCalloutHeadingOwnedPublic(t *testing.T) {
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			raw, page, before := agreementProseP0Failures(t, r.Body)
			pr, pp, after := agreementProseP0Failures(t, r.Private)
			if raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !maps.Equal(agreementMixedCurrent(before), agreementMixedCurrent(r.Before)) || !maps.Equal(agreementMixedCurrent(after), agreementMixedCurrent(r.After)) || !agreementCalloutHeadingProjection(&r.Source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics) {
				t.Fatal("caught: complete callout heading public and diagnostic ledgers")
			}
			selected := agreementCalloutHeadingSelected(t, r)
			k, a, w := agreementCalloutHeadingDifference(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, before)
			if k != "debt" || a != "#1011 stage 8" || w != "judge" {
				t.Fatal("caught: exact callout heading authority and original source membership")
			}
		})
	}
}
func TestAgreementCalloutHeadingOwnedRefusals(t *testing.T) {
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementCalloutHeadingSelected(t, r)
			refuse := func(c agreementCase, x *agreementFailure, html string, page *agreementHTML, ds []render.Diagnostic, fs []agreementFailure) {
				t.Helper()
				k, a, w := agreementCalloutHeadingDifference(c, x, html, page, ds, fs)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: callout heading refuses changed complete source or context")
				}
			}
			for _, c := range []agreementCase{{Body: r.Body + "!"}, {Body: r.Body, Title: "outside"}, {Body: r.Body, Companions: capturedBodies{"outside.md": "outside"}}} {
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			c := agreementCase{Body: r.Body}
			refuse(c, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML, nil, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML+"!", &r.Page, r.Diagnostics, r.Before)
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "outside" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				refuse(c, &x, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			altered := r.Page
			altered.Headings = append(slices.Clone(r.Page.Headings), "outside")
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			altered = r.Page
			altered.Citations = append(slices.Clone(r.Page.Citations), agreementCitation{Target: "outside"})
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			ds := append(slices.Clone(r.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(c, &f, r.HTML, &r.Page, ds, r.Before)
			for j := range r.Before {
				fs := slices.Delete(slices.Clone(r.Before), j, j+1)
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, fs)
				if agreementCalloutHeadingProjection(&r.Source, fs, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every original callout heading receipt retained")
				}
			}
			for j := range r.After {
				fs := slices.Delete(slices.Clone(r.After), j, j+1)
				if agreementCalloutHeadingProjection(&r.Source, r.Before, fs, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every private callout heading receipt retained")
				}
			}
			source := r.Source
			source.IDs = append(slices.Clone(r.Source.IDs), "outside")
			if agreementCalloutHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: whole callout heading source allocation retained")
			}
		})
	}
}
func TestAgreementCalloutHeadingOwnedCensus(t *testing.T) {
	rows := agreementCalloutHeadingProspects()
	if len(rows) != 313 {
		t.Fatal("caught: whole callout heading prospect roster")
	}
	qualified := map[[3]string]bool{}
	for i := range rows {
		r := &rows[i]
		raw, page, before := agreementProseP0Failures(t, r.Body)
		var selected agreementFailure
		seen := 0
		for j := range before {
			f := &before[j]
			if agreementSignature(f) == r.Selected {
				selected = *f
				seen++
			}
		}
		if seen != 1 {
			t.Fatal("caught: every original callout heading prospect exists")
		}
		source := agreementCalloutHeadingReading(r.Body, &selected, &page)
		eligible := false
		if source.Valid {
			pr, pp, after := agreementProseP0Failures(t, source.Private)
			eligible = agreementCalloutHeadingProjection(&source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics)
		}
		if eligible != r.Eligible {
			t.Fatalf("caught: whole callout heading eligibility and refusal set case=%s selected=%s got=%t want=%t", r.Case, r.Selected, eligible, r.Eligible)
		}
		if eligible {
			qualified[[3]string{r.Body, r.Case, r.Selected}] = true
		}
	}
	declared := map[[3]string]bool{}
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		declared[[3]string{r.Body, r.Case, r.Selected}] = true
	}
	if len(declared) != 19 || !maps.Equal(qualified, declared) {
		t.Fatal("caught: complete callout heading eligible declaration set")
	}
}
func TestAgreementCalloutHeadingOwnedProjectionRefusals(t *testing.T) {
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			reject := func(s *agreementCalloutHeadingSource, page, privatePage *agreementHTML, ds, pds []render.Diagnostic) {
				t.Helper()
				if agreementCalloutHeadingProjection(s, r.Before, r.After, page, privatePage, ds, pds) {
					t.Fatal("caught: callout heading refuses changed whole projection")
				}
			}
			reject(nil, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, nil, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, &r.Page, nil, r.Diagnostics, r.PrivateDiagnostics)
			s := r.Source
			s.Valid = false
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.IDs = append(slices.Clone(s.IDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.PrivateIDs = append(slices.Clone(s.PrivateIDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.Native.Names = maps.Clone(s.Native.Names)
			f := agreementCalloutHeadingSelected(t, r)
			s.Native.Names[f.Fragment] = true
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			pp := r.PrivatePage
			pp.Headings = append(slices.Clone(pp.Headings), "outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Citations = append(slices.Clone(pp.Citations), agreementCitation{Target: "outside"})
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Blocks = append(slices.Clone(pp.Blocks), "^outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			ds := append(slices.Clone(r.PrivateDiagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			reject(&r.Source, &r.Page, &r.PrivatePage, r.Diagnostics, ds)
		})
	}
}
func TestAgreementCalloutHeadingOwnedPhysicalRefusals(t *testing.T) {
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementCalloutHeadingSelected(t, r)
			if agreementCalloutHeadingReading(r.Body, nil, &r.Page).Valid || agreementCalloutHeadingReading(r.Body, &f, nil).Valid {
				t.Fatal("caught: callout heading physical context")
			}
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				if agreementCalloutHeadingReading(r.Body, &x, &r.Page).Valid {
					t.Fatal("caught: callout heading refuses another physical property or signature")
				}
			}
			changed := r.Page
			changed.Headings = append(slices.Clone(changed.Headings), "outside")
			if agreementCalloutHeadingReading(r.Body, &f, &changed).Valid {
				t.Fatal("caught: callout heading refuses altered physical allocation")
			}
		})
	}
}

func TestAgreementCalloutHeadingOwnedReaderRefusals(t *testing.T) {
	for _, body := range []string{"## A\n## A\n", string([]byte{0xff}), "`code`\n> [!note] title\n> # A\n", "~~~\ncode\n~~~\n> [!note] title\n> # A\n"} {
		if agreementCalloutHeadingRead(body).Valid {
			t.Fatal("caught: callout heading refuses absent opener code or invalid source bytes")
		}
	}
	for i := range agreementCalloutHeadingDeclarations() {
		r := &agreementCalloutHeadingDeclarations()[i]
		if len(r.Source.Original.Openers) == 0 || len(r.Source.PrivateReading.Openers) == 0 || !cmp.Equal(r.Source.Original.Plain, r.Source.Original.Page) || !cmp.Equal(r.Source.PrivateReading.Plain, r.Source.PrivateReading.Page) {
			t.Fatal("caught: complete original and private callout shells and grammar relationship")
		}
	}
}
